import os,tempfile,subprocess
s="'use strict';
const get=async u=>{let r=await fetch(u,{signal:AbortSignal.timeout(4000)});return r.json()},norm=u=>{try{let x=new URL(u);return /^((www\.)?chatgpt\.com)$/.test(x.hostname)?x.pathname.replace(/\/$/,''):''}catch{return ''}};
const hash=x=>require('node:crypto').createHash('sha256').update(String(x)).digest('hex').slice(0,12);
async function main(){
 let [m,targets,o,w]=await Promise.all([get('http://127.0.0.1:17448/api/supervisor-watchdog/managed-chats?inspect=0'),get('http://127.0.0.1:17410/json/list'),get('http://127.0.0.1:17448/api/operator-lifecycle'),get('http://127.0.0.1:17448/api/supervisor-watchdog?detect=0')]);
 let rows=(m.chats||[]).map(z=>{
 let expected=norm(z.url),match=targets.filter(t=>norm(t.url)===expected);
 let byConversation=targets.filter(t=>{const path=norm(t.url),id=expected.split('/').pop();return id&&path.endsWith('/'+id)});
 return {name:z.name,exact:match.length,byConversation:byConversation.length,targetKinds:match.map(t=>({idHash:hash(t.id),type:t.type,route:t.url.includes('/g/')?'project': 'direct'})),sameConversationOtherRoute:byConversation.length>match.length};
 });
 console.log(JSON.stringify({at:new Date().toISOString(),targets:targets.length,rows,paused:o.queuePaused,watchdogOff:w.config?.mode==='off',hasDuplicateTargets:rows.some(x=>x.byConversation>1)}))
}main().catch(e=>console.log(JSON.stringify({error:e.message})))"
